function getDiseaseInfo(label,language='EN'){const text=String(label||'').toLowerCase();const item=diseaseInfo.find(d=>d.keys.some(k=>text.includes(k)))||{title:label||'Unknown class',cause:`Your Teachable Machine model classified this image as “${label}”. The exact disease cannot safely be inferred unless the model's class name identifies it clearly.`,risk:'Risk depends on the crop, pathogen, infection stage and field conditions; a model label is not a confirmed diagnosis.',solution:'Compare symptoms with reliable crop-health guidance and contact a Rwanda district agronomist or RAB extension officer before treatment.',advice:'Use a sharp photo of the whole plant and affected leaf, check neighbouring plants, and avoid pesticides until the diagnosis is confirmed.'};if(language!=='RW')return item;const rwDisease={ 'Healthy plant':{title:'Igihingwa kimeze neza',cause:'MuderI yerekanye ko ifoto isa n’igihingwa kizima. Ifoto imwe ntihamya ko igihingwa cyose kidafite indwara.',risk:'Komeza kugenzura; indwara nshya zishobora kutagaragara ako kanya.',solution:'Komeza isuku mu murima, ukoreshe imbuto cyangwa uduti bizima kandi ugenzure ibihingwa buri gihe.',advice:'Fata amafoto asobanutse y’impande zombi z’amababi niba hagaragaye ibimenyetso bishya.'},'Fall armyworm (maize pest)':{title:'Udusimba twangiza ibigori (Fall armyworm)',cause:'Ibinyabwoya bya Spodoptera frugiperda byangiza amababi, umutwe n’imyumbati y’ibigori.',risk:'Iyo ari twinshi dushobora kugabanya umusaruro kandi tugakwira vuba.',solution:'Genzura umurima kenshi, ukureho amagi cyangwa ibinyabwoya bikiri bito aho bishoboka, kandi ubaze umujyanama w’ubuhinzi ku ngamba zemewe.',advice:'Ntukoreshe umuti ushingiye ku ifoto yonyine; kurikiza amabwiriza y’umuti n’inama z’abajyanama.'},'Cassava mosaic disease':{title:'Indwara ya Cassava Mosaic',cause:'Indwara iterwa na virusi ikwirakwizwa n’amasazi y’umweru n’uduti two gutera twanduye.',risk:'Ishobora guhindura imiterere y’amababi, gutinza imikurire no kugabanya umusaruro w’imizi.',solution:'Koresha uduti twiza n’amoko agirwa inama na RAB; kurikiza inama z’inzego z’ubuhinzi ku bimera byanduye.',advice:'Saba RAB cyangwa umukozi w’ubuhinzi kwemeza indwara no kukwereka aho wabona uduti twiza.'},'Cassava brown streak disease':{title:'Indwara ya Cassava Brown Streak',cause:'Indwara ya virusi ikwirakwizwa n’amasazi y’umweru n’uduti twanduye; ishobora kwangiza imizi.',risk:'Imizi ishobora kwangirika cyane nubwo igihingwa kigaragara nk’ikimeze neza hejuru.',solution:'Koresha uduti twiza n’amoko asabwa n’inzego z’ubuhinzi; kurikiza amabwiriza ku bimera bikekwa ko birwaye.',advice:'Ntukwirakwize uduti twakuwe ku bimera bikekwa ko byanduye.'},'Potato late blight':{title:'Indwara ya Late Blight y’ibirayi',cause:'Iterwa na Phytophthora infestans; ikwirakwira vuba mu gihe gikonje, gifite ubuhehere n’imvura.',risk:'Ishobora kwangiza amababi n’ibirayi mu gihe gito iyo ikirere kibereye indwara.',solution:'Koresha imbuto z’ibirayi nzima, genzura amababi n’ibiti nyuma y’imvura kandi ubaze umujyanama ku ngamba zemewe.',advice:'Genzura umurima kenshi nyuma y’imvura kandi uhamagare umukozi w’ubuhinzi vuba.'},'Early blight':{title:'Indwara ya Early Blight',cause:'Indwara y’uduhumyo ishobora gutera ibibara byijimye ku mababi ashaje.',risk:'Iyo amababi menshi yangiritse, imikurire n’umusaruro bishobora kugabanuka.',solution:'Hinduranya ibihingwa, kura ibisigazwa byanduye kandi wirinde ko amababi ahora atose.',advice:'Emeza igihingwa n’indwara mbere yo guhitamo umuti.'},'Bacterial wilt':{title:'Kuma kw’igihingwa guterwa na bagiteri',cause:'Bagiteri yo mu butaka cyangwa mu mazi ishobora kubuza amazi kugera mu bice by’igihingwa.',risk:'Ishobora gutera kuma vuba kandi ikaguma mu butaka cyangwa mu bikoresho byo gutera byanduye.',solution:'Koresha imbuto/uduti bizima, wirinde kwimura ubutaka bwanduye kandi ukurikize inama z’isuku n’ihinduranya ry’ibihingwa.',advice:'Saba umujyanama kwemeza indwara; nta muti umwe wo mu rugo uvura buri gihe.'},'Anthracnose':{title:'Indwara ya Anthracnose',cause:'Indwara y’uduhumyo ishobora gutera ibibara byijimye ku mababi, ku biti, ku bishishwa cyangwa ku mbuto.',risk:'Ishobora kwangiza umusaruro ugurishwa kandi ikiyongera mu gihe cy’ubushuhe.',solution:'Koresha imbuto nziza, hinduranya ibihingwa kandi ukureho ibisigazwa byanduye.',advice:'Saba umujyanama gutandukanya iyi ndwara n’izindi zitera ibibara.'},'Bacterial spot':{title:'Ibibara biterwa na bagiteri',cause:'Indwara ya bagiteri ishobora gutera utubara twijimye ku mababi no ku mbuto.',risk:'Imvura n’amazi asimbukira ku mababi bishobora gukwirakwiza indwara.',solution:'Irinde gukora mu bimera bitose, koresha imbuto nzima kandi ukurikize isuku n’ihinduranya ry’ibihingwa.',advice:'Ntukoreshe inama y’umuti w’ikindi gihingwa utabanje kubaza umujyanama.'},'Leaf mold':{title:'Indwara ya Leaf Mold',cause:'Indwara y’uduhumyo ikunda ahantu hafite ubuhehere bwinshi n’amababi yegeranye.',risk:'Ishobora gutera umuhondo no kugwa kw’amababi, bikagabanya umusaruro.',solution:'Ongera umwuka hagati y’ibihingwa, irinde gutosa amababi kandi ukureho ibisigazwa byanduye.',advice:'Emeza ubwoko bw’igihingwa n’indwara mbere yo gukoresha umuti.'}};return {...item,...(rwDisease[item.title]||{title:item.title,cause:'Ibyo muderi yerekanye ntibihagije kwemeza indwara. Saba umujyanama w’ubuhinzi gusuzuma igihingwa.',risk:'Ibyago biterwa n’igihingwa, indwara n’uko yageze kure.',solution:'Gereranya ibimenyetso n’amakuru yizewe kandi ubaze RAB cyangwa umukozi w’ubuhinzi mbere yo kuvura.',advice:'Koresha ifoto isobanutse kandi wirinde imiti kugeza indwara yemejwe.'})};}
