function weatherAdvice(){if(!weather?.daily)return lang==='RW'?'Hitamo akarere kugira ngo ubone inama zishingiye ku iteganyagihe.':'Select a district and load the forecast to get weather-based planning advice.';const rain=weather.daily.precipitation_sum.reduce((a,b)=>a+(b||0),0);const wet=weather.daily.precipitation_probability_max.filter(x=>x>=60).length;if(rain>=80||wet>=7)return lang==='RW'?'Muri iki gihe hateganyijwe imvura nyinshi: subika gutera imiti mbere y’imvura, fungura inzira z’amazi, irinde gukorera mu butaka bwuzuye amazi kandi ugenzure indwara z’uduhumyo. Tera gusa igihe ubutaka n’inama z’abajyanama bibyemeye.':'Wet spell likely in this forecast window: delay pesticide spraying before rain, keep drainage channels clear, avoid working saturated soil and inspect crops for fungal disease. Plant only when local soil moisture and extension advice are suitable.';if(rain<=15&&wet<=2)return lang==='RW'?'Imvura iteganyijwe ni nke: gumisha ubuhehere mu butaka ukoresheje ibishingwe bitwikira ubutaka, genzura amazi ahari kandi ntushingire ku iteganyagihe rimwe gusa mu gufata icyemezo cyo gutera.':'Relatively dry forecast window: conserve soil moisture with mulch, check water availability, avoid planting solely on a single forecast, and plan supplemental watering where feasible.';return lang==='RW'?'Imvura ishobora guhindagurika: tegura inzira z’amazi ku misozi, gumisha ubuhehere ukoresheje ibishingwe, genzura imvura y’akarere mbere yo gutera kandi wirinde gutera imiti mbere y’imvura iteganyijwe.':'Mixed rainfall outlook: prepare drainage on sloping plots, conserve moisture with mulch, check local rainfall before sowing and avoid spraying immediately before forecast rain.';}
