async function detect(file){if(!file)return;setBusy(true);setModelStatus(lang==='RW'?'Tegereza gato, turimo gufungura uburyo bwo gusuzuma igihingwa…':'Getting the crop checker ready…');let objectUrl='';try{const tm=await import('@teachablemachine/image');if(!cachedTMModel){if(!cachedTMModelPromise){cachedTMModelPromise=tm.load(MODEL_URL+'model.json',MODEL_URL+'metadata.json').then(m=>{cachedTMModel=m;return m}).catch(e=>{cachedTMModelPromise=null;throw e;});}cachedTMModel=await cachedTMModelPromise;}const model=cachedTMModel;const img=new Image();objectUrl=URL.createObjectURL(file);img.src=objectUrl;await new Promise((res,rej)=>{img.onload=res;img.onerror=rej});const predictions=await model.predict(img);predictions.sort((a,b)=>b.probability-a.probability);const best=predictions[0];const disease=getDiseaseInfo(best.className,lang);setModelStatus({label:best.className,confidence:best.probability,...disease});api('/api/scan-logs',{method:'POST',body:JSON.stringify({filename:file.name,prediction:best.className,confidence:best.probability})}).catch(()=>{});}catch(e){setModelStatus((lang==='RW'?'Ntidushoboye gusuzuma ifoto: ':'Could not check this photo: ')+e.message+(lang==='RW'?' Reba internet wongere ugerageze.':' Check your internet and try again.'));}finally{if(objectUrl)URL.revokeObjectURL(objectUrl);setBusy(false)}}
